import 'package:flutter/material.dart'; import 'package:fl_chart/fl_chart.dart';
class InsightsPage extends StatelessWidget { const InsightsPage({super.key}); @override Widget build(BuildContext context){ return Scaffold(appBar: AppBar(title: Text('Insights'), automaticallyImplyLeading: false), body: ListView(padding: EdgeInsets.all(24), children: [SizedBox(height:180, child: BarChart(BarChartData(barGroups: List.generate(7, (i)=> BarChartGroupData(x:i, barRods:[BarChartRodData(toY:(i*1.2+2), width:18, borderRadius: BorderRadius.circular(6))])))), ), SizedBox(height:24), Text('Category Split'), SizedBox(height:140, child: PieChart(PieChartData(sections:[PieChartSectionData(value:40, title:'Work'), PieChartSectionData(value:30, title:'Build'), PieChartSectionData(value:20, title:'Learn'), PieChartSectionData(value:10, title:'Life')])))])); } }